mapper.select:
SELECT m.id, m.bus_no, m.name, m.total_volume, m.active_flag, m.category_code, m.manufacturer_text, m.package_unit_code, ( SELECT c.price_value FROM adm_charge_item_definition c WHERE c.instance_table = 'med_medication_definition' AND c.instance_id = m.id AND c.price_type_code = 'SALE' AND c.is_deleted = 0 ORDER BY COALESCE(c.priority, 2147483647), c.id LIMIT 1 ) AS retail_price FROM med_medication_definition m
m.is_deleted = 0
AND (m.bus_no LIKE CONCAT('%', #{query.keyword}, '%') OR m.name LIKE CONCAT('%', #{query.keyword}, '%') OR m.merchandise_name LIKE CONCAT('%', #{query.keyword}, '%') OR m.py_str LIKE CONCAT('%', #{query.keyword}, '%') OR m.wb_str LIKE CONCAT('%', #{query.keyword}, '%'))
AND m.category_code = #{query.categoryCode}
AND m.active_flag = #{query.activeFlag}
ORDER BY m.created_at DESC, m.id DESC
